Method.Source:
/// <summary>
/// Is the agreement default commitment = vendor category value commitment?
/// </summary>
/// <returns>True if agreement is vendor category value commitment; otherwise, false.</returns>
public boolean METIsVendorCategoryProductVolume()
{
    return this.DefaultAgreementLineType == CommitmentType::METVendorCategoryProductVolume;
}

/// <summary>
/// Update method
/// </summary>
public void update()
{
    AgreementHeader agreementHeaderOrg = this.orig();

    next update();

    if (this.DefaultAgreementLineType != agreementHeaderOrg.DefaultAgreementLineType)
    {
        METEcoResCategoryHierarchyName categoryName = AgreementLine::metSetCategoryHierarchyName(this);
        AgreementLine agreementLine;

        update_recordset agreementLine
            setting METCategoryHierarchyName = categoryName
                where agreementLine.Agreement == this.RecId;
    }


}
